5  int year = 2000;
6
7  // If divisible by 400, it's a leap year
8  if (year % 400 == 0) {
9    printf("Leap Year");
10  }
11
12  // At this point, we know it's not divisible by 400
13  // If it's a century year, it's not a leap year
14  else if (year % 100 == 0) {
15    printf("Not a Leap Year");
16  }
17  
18  // At this point we know it's not a century year
19  // If a non century year is divisible by 4,
20  // It's a leap year
21  else if (year % 4 == 0) {
22    printf("Leap Year");
23  }
24
25  // All other remaining years are not a leap year
26  else {
27    printf("Not a Leap Year");
